        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 6.0, 'max': 7, 'label': 'BETA'})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'mean': 9.666666666666666, 'max': 14, 'label': 'BETA'})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 7.666666666666667, 'max': 12, 'label': 'BETA'})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'label': 'EMPTY'})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 12.333333333333334, 'max': 16, 'label': 'BETA'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 4.0, 'max': 4, 'label': 'BETA'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 10.0, 'max': 10, 'label': 'BETA'})
